package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.io.NumberInput;
import java.io.*;
import java.math.*;
import java.text.DateFormat;
import java.text.FieldPosition;
import java.text.ParseException;
import java.text.ParsePosition;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.Calendar;
import java.util.Date;
import java.util.Locale;
import java.util.TimeZone;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

public class StdDateFormat_parseAsISO8601_TriageGen1Test {

    private StdDateFormat stdDateFormat;
    private TimeZone utc;

    @Before
    public void setUp() {
        utc = TimeZone.getTimeZone("UTC");
        stdDateFormat = new StdDateFormat(utc, Locale.US);
    }

    /**
     * Helper to create a subclass to expose the protected method
     */
    private static class TestableStdDateFormat extends StdDateFormat {
        public TestableStdDateFormat(TimeZone tz, Locale loc) {
            super(tz, loc);
        }

        @Override
        public Date parseAsISO8601(String dateStr, ParsePosition pos) {
            return super.parseAsISO8601(dateStr, pos);
        }
    }

    private TestableStdDateFormat getTestableInstance() {
        return new TestableStdDateFormat(utc, Locale.US);
    }

    @Test
    public void testParsePlainDate() {
        TestableStdDateFormat df = getTestableInstance();
        String dateStr = "2023-10-27";
        ParsePosition pos = new ParsePosition(0);
        Date result = df.parseAsISO8601(dateStr, pos);

        assertNotNull(result);
        Calendar cal = Calendar.getInstance(utc);
        cal.setTime(result);
        assertEquals(2023, cal.get(Calendar.YEAR));
        assertEquals(Calendar.OCTOBER, cal.get(Calendar.MONTH));
        assertEquals(27, cal.get(Calendar.DAY_OF_MONTH));
    }

    @Test
    public void testParseZuluWithMissingMilliseconds() {
        TestableStdDateFormat df = getTestableInstance();
        // Format: YYYY-MM-DDTHH:mm:ssZ (colon at len-4)
        String dateStr = "2023-10-27T10:20:30Z";
        ParsePosition pos = new ParsePosition(0);
        Date result = df.parseAsISO8601(dateStr, pos);

        assertNotNull(result);
        Calendar cal = Calendar.getInstance(utc);
        cal.setTime(result);
        assertEquals(10, cal.get(Calendar.HOUR_OF_DAY));
        assertEquals(30, cal.get(Calendar.SECOND));
    }

    @Test
    public void testParseZuluWithMilliseconds() {
        TestableStdDateFormat df = getTestableInstance();
        String dateStr = "2023-10-27T10:20:30.123Z";
        ParsePosition pos = new ParsePosition(0);
        Date result = df.parseAsISO8601(dateStr, pos);

        assertNotNull(result);
        Calendar cal = Calendar.getInstance(utc);
        cal.setTime(result);
        assertEquals(10, cal.get(Calendar.HOUR_OF_DAY));
    }

    @Test
    public void testParseWithTimeZoneOffsetAndColon() {
        TestableStdDateFormat df = getTestableInstance();
        // Testing the removal of colon in offset: +05:00 -> +0500
        // And the injection of .000 because c (len-9) is a digit
        String dateStr = "2023-10-27T10:20:30+05:00";
        ParsePosition pos = new ParsePosition(0);
        Date result = df.parseAsISO8601(dateStr, pos);

        assertNotNull(result);
        Calendar cal = Calendar.getInstance(utc);
        cal.setTime(result);
        // 10:20:30 +05:00 is 05:20:30 UTC
        assertEquals(5, cal.get(Calendar.HOUR_OF_DAY));
    }

    @Test
    public void testParseWithTimeZoneOffsetNoColon() {
        TestableStdDateFormat df = getTestableInstance();
        // Testing c == '+' or '-' (missing minutes) -> appends '00'
        String dateStr = "2023-10-27T10:20:30+05";
        ParsePosition pos = new ParsePosition(0);
        Date result = df.parseAsISO8601(dateStr, pos);

        assertNotNull(result);
        Calendar cal = Calendar.getInstance(utc);
        cal.setTime(result);
        assertEquals(5, cal.get(Calendar.HOUR_OF_DAY));
    }

    @Test
    public void testParseWithoutTimeZoneIndicator() {
        TestableStdDateFormat df = getTestableInstance();
        // Should append .000 and Z
        String dateStr = "2023-10-27T10:20:30";
        ParsePosition pos = new ParsePosition(0);
        Date result = df.parseAsISO8601(dateStr, pos);

        assertNotNull(result);
        Calendar cal = Calendar.getInstance(utc);
        cal.setTime(result);
        assertEquals(10, cal.get(Calendar.HOUR_OF_DAY));
    }

    @Test
    public void testParseWithoutTimeZoneIndicatorAndShortTime() {
        TestableStdDateFormat df = getTestableInstance();
        // Testing timeLen <= 8 condition
        String dateStr = "2023-10-27T10:20";
        ParsePosition pos = new ParsePosition(0);
        Date result = df.parseAsISO8601(dateStr, pos);

        assertNotNull(result);
        Calendar cal = Calendar.getInstance(utc);
        cal.setTime(result);
        assertEquals(10, cal.get(Calendar.HOUR_OF_DAY));
        assertEquals(20, cal.get(Calendar.MINUTE));
    }

    @Test
    public void testParseWithMillisecondsAndTimeZoneOffset() {
        TestableStdDateFormat df = getTestableInstance();
        // Ensure logic for injecting .000 works when offset is present
        // dateStr: 2023-10-27T10:20:30.123+05:00
        // len = 25. len-9 = 16. charAt(16) is '3' (digit)
        String dateStr = "2023-10-27T10:20:30.123+05:00";
        ParsePosition pos = new ParsePosition(0);
        Date result = df.parseAsISO8601(dateStr, pos);

        assertNotNull(result);
        Calendar cal = Calendar.getInstance(utc);
        cal.setTime(result);
        assertEquals(5, cal.get(Calendar.HOUR_OF_DAY));
    }
}
